898	    font-size:clamp(1.4rem,2.2vw,2rem);letter-spacing:-.01em;
899	    text-transform:uppercase;color:var(--ink);}
900	  .process-p{font-family:var(--font);font-weight:300;font-size:16px;
901	    color:rgba(22,20,15,.78);max-width:34ch;}
