904	
905	  .process-stick{position:sticky;top:max(24px,calc((100svh - 495px) / 2));
906	    align-self:start;}
907	  .process-sheet{display:block;width:100%;max-width:880px;height:auto;
908	    aspect-ratio:880/495;}
909	
910	  /* --- linjehierarkin, K3:s klasser, V3c:s egna tokens (index.html:143-149) */
911	  .process-sheet .contour{fill:none;stroke:var(--ink);stroke-width:var(--contour-line);}
912	  .process-sheet .dimline{fill:none;stroke:var(--hair-ink);stroke-width:var(--contour-hair);}
913	  .process-sheet .guide{fill:none;stroke:var(--hair-ink);stroke-width:var(--contour-hair);
914	    stroke-dasharray:var(--contour-dash);}
915	  .process-sheet .leader{fill:none;stroke:var(--hair-ink);stroke-width:var(--contour-hair);}
916	  .process-sheet .hatch{fill:url(#p-hatch-pattern);stroke:none;}
917	  .process-sheet .leaddot{fill:var(--hair-ink);stroke:none;}
918	  .process-sheet #p-hatch-pattern line{stroke:var(--hair-ink);}
919	  .process-sheet path,.process-sheet rect{stroke-linecap:butt;stroke-linejoin:miter;}
920	
921	  /* --- ritmekaniken. pathLength="1" normaliserar varje bana; enheten
922	     *1px på stroke-dashoffset är obligatorisk (K3-r8/index.html:263-268).
923	     En streckad hjälplinje kan inte dash-ritas (dasharray gör redan ett
924	     jobb), så guide/stations/ledgers/hatch avslöjas med clip-path. */
925	  .process-sheet .draw{stroke-dasharray:1px;stroke-dashoffset:calc((1 - var(--p-l)) * 1px);
926	    /* Markörer (pilspetsar) positioneras på banans vertex, inte på den
927	       synliga stroken - stroke-dashoffset klipper dem inte (R5-fyndet).
928	       Snäpp-opacitet döljer dem tills banan faktiskt börjat rita. */
929	    opacity:clamp(0,calc(var(--p-l) * 9999),1);}
930	  .process-sheet .wipe{clip-path:inset(0 calc((1 - var(--p-l)) * 100%) 0 0);}
931	
932	  .process-sheet .callout{font-family:var(--font);font-weight:600;font-size:12px;
933	    letter-spacing:.16em;text-transform:uppercase;fill:var(--hair-ink);
934	    opacity:var(--p-t);}
935	  .process-sheet .measure{font-family:var(--f-display);font-weight:700;
936	    font-size:44px;font-variant-numeric:tabular-nums;
937	    /* PLAN 020 Target D. Tonbytet: vid --k6 = 1 (steg 06 i mitten) är
938	       kedjan --hair-ink, inte längre blå - H-33, ett blått moment per
939	       skärm, inte ett kvarglömt (R5-fyndet: siffrorna förblev accent
940	       efter fallet). Skärm 05: siffrorna viker till 0,7 opacitet när
941	       Calyx-bilden landar (TASTE § 4.8: bilden är skärmens auktoritet)
942	       utan att försvinna helt - multiplicerat med fade-in-tonen --p-t,
943	       inte i stället för den. */
944	    fill:color-mix(in srgb, var(--c-accent), var(--hair-ink) calc(100% * var(--k6)));
945	    opacity:calc(var(--p-t) * (1 - 0.3 * var(--k5)));transform-box:fill-box;
946	    /* 44 -> 12px = faktor 1 - 0.7273. transform-box:fill-box: annars
947	       skalar siffran mot SVG:ns user-space-nollpunkt (K3-fällan). */
948	    transform:scale(calc(1 - 0.7273 * var(--k6)));}
949	  #p-m320,#p-m768{transform-origin:50% 100%;}
950	  #p-m1440{transform-origin:100% 100%;}
951	
952	  .process-sheet .p-live{
953	    clip-path:inset(0 0 calc((1 - var(--k5)) * 100%) 0);
954	    /* PLAN 046: gråskalan är ritningens material; färgen kommer när ritningen
955	       blir sida. Samma fönster som resten av steg 06:s tillbakadragning
956	       (.measure tonbyte och skala, #p-guides/#p-ledgers/#p-hatch opacitet,
957	       .contour viktfall) - en gest i fyra egenskaper, inte fyra gester. */
958	    filter:grayscale(calc(1 - var(--k6))) contrast(1.05);}
959	
960	  /* s-process-06: konturernas viktfall och hjälplinjer/skraffering som
961	     tonar till 0,35 opacitet (bara hjälplinjer och skraffering, inte
962	     måttlinjer eller ledare - R5-fyndet om selektorns bredd). */
963	  .process-sheet .contour{stroke-width:calc(var(--contour-line) - 0.75px * var(--k6));}
964	  /* PLAN 020 Target E. AVVIKELSE (R5): klasselektorn .guide,.hatch
965	     träffade även #p-rev (revisionsfältets skraffering bär class="hatch
966	     wipe"), så 07:s revisionscell tonades permanent till 0,35 trots att
967	     den ritas EFTER --k6:s fönster har passerat. Id-selektorn träffar
968	     bara de tre element som faktiskt ska tona; #p-rev står i full ton. */
969	  #p-guides,#p-ledgers,#p-hatch{opacity:calc(1 - 0.65 * var(--k6));}
970	
971	  /* PLAN 019 Step 3. --k1..--k7 är EN andel (0 till 1) av respektive
972	     stegs eget fönster [--sN,--eN], normalt deklarerade (inherits:true
973	     per spec), så arkets alla barn ärver dem - till skillnad från
974	     --p-l/--p-t/--p-thin/--p-fill/--p-fall som är inherits:false
975	     (R5-fyndet) och måste sättas per konsument. --s1..--e7 har CSS-
976	     fallback här (no-JS-golvet); JS (measureAct) skriver de uppmätta. */
977	  #process{
978	    --s1:.09; --e1:.16; --s2:.19; --e2:.26; --s3:.29; --e3:.36;
979	    --s4:.39; --e4:.46; --s5:.49; --e5:.56; --s6:.59; --e6:.66;
980	    --s7:.69; --e7:.76;
981	    --k1:clamp(0,calc((var(--sc-ps,0) - var(--s1)) / (var(--e1) - var(--s1))),1);
982	    --k2:clamp(0,calc((var(--sc-ps,0) - var(--s2)) / (var(--e2) - var(--s2))),1);
983	    --k3:clamp(0,calc((var(--sc-ps,0) - var(--s3)) / (var(--e3) - var(--s3))),1);
984	    --k4:clamp(0,calc((var(--sc-ps,0) - var(--s4)) / (var(--e4) - var(--s4))),1);
985	    --k5:clamp(0,calc((var(--sc-ps,0) - var(--s5)) / (var(--e5) - var(--s5))),1);
986	    --k6:clamp(0,calc((var(--sc-ps,0) - var(--s6)) / (var(--e6) - var(--s6))),1);
987	    --k7:clamp(0,calc((var(--sc-ps,0) - var(--s7)) / (var(--e7) - var(--s7))),1);
988	  }
989	
990	  /* --- per-bana andelar [a,b] av stegets EGNA --kN (0 till 1), inte av
991	     rå --sc-ps. Ordningen inom steget som tidigare; två banor i samma
992	     steg överlappar med högst halva sitt fönster (perf 4). Utropen
993	     (rad 3 i device-tabellen) läser en fast bredd 0,15 av --kN. */
994	  /* PLAN 040 (loop 3): konturen är hel medan steg 01 läses; entréskärmens
995	     högerspalt bär en ram, inte ett streck (H-15). Glyfen följer efter.
996	     Ingen överlappning (0-0,30 / 0,30-0,70): perf 4:s halva-fönstret-tak. */
997	  #p-outline{--p-l:clamp(0,calc((var(--k1) - 0) / 0.30),1);}
998	  /* PLAN 020 Target C: #p-glyph är en egen <path> (kopia av
999	     #alunix-mark-path), inte ett <use> - se markupkommentaren. Dash-draw
1000	     fungerar på en <path> (pathLength stöds), så glyfen ritas som
1001	     konturen: samma .draw-mekanik och samma snäpp-opacitet mot
1002	     markörer som alla andra banor, ingen egen opacitetston. */
1003	  .process-sheet #p-glyph{fill:none;stroke:var(--hair-ink);stroke-width:23.7;
1004	    stroke-linejoin:miter;--p-l:clamp(0,calc((var(--k1) - 0.30) / 0.40),1);}
1005	
1006	  #p-guides{--p-l:clamp(0,calc((var(--k2) - 0) / 0.45),1);}
1007	  #p-dim-width{--p-l:clamp(0,calc((var(--k2) - 0.3) / 0.45),1);}
1008	  #p-stations{--p-l:clamp(0,calc((var(--k2) - 0.6) / 0.3),1);}
1009	  #p-m320,#p-m768,#p-m1440{--p-t:clamp(0,calc((var(--k2) - 0.75) / 0.15),1);}
1010	
1011	  #p-opening{--p-l:clamp(0,calc((var(--k3) - 0) / 0.45),1);}
1012	  #p-dim-gutter{--p-l:clamp(0,calc((var(--k3) - 0.3) / 0.4),1);}
1013	  #p-lead-169{--p-l:clamp(0,calc((var(--k3) - 0.6) / 0.35),1);}
1014	  #p-c-gutter{--p-t:clamp(0,calc((var(--k3) - 0.55) / 0.15),1);}
1015	  #p-c-169{--p-t:clamp(0,calc((var(--k3) - 0.85) / 0.15),1);}
