1049	     befintlig rad ovan rörd. Fyra tokens vänder hela aktens ritregister
1050	     (.contour/.dimline/.guide/.leader läser --ink/--hair-ink,
1051	     .measure läser --c-accent, .ledger/.ledger-row läser
1052	     --c-line-on-paper, .process/.principles sätter bg/color ur --bg/
1053	     --ink) - se planens eget "Varför tokens och inte en omskrivning
1054	     per regel". --hair-ink substituerar vid DEKLARATIONSTILLFÄLLET
1055	     (color-mix(in srgb, var(--ink) 62%, var(--bg)), rad 156) och ärver
1056	     därför INTE de omskrivna --ink/--bg härifrån; skriven om separat. */
1057	  :root[data-process="invert"] #process,
1058	  :root[data-process="invert"] .principles{
1059	    --bg: var(--c-black);
1060	    --ink: var(--c-paper);
1061	    --c-line-on-paper: var(--hairline-dark);
1062	    --c-accent: var(--c-accent-on-dark);
1063	    --hair-ink: color-mix(in srgb, var(--c-paper) 62%, var(--c-black));
1064	  }
1065	  /* De fyra hårdkodade bläcktonerna (rgba(), ingen token) blir nära
1066	     svarta mot mörkt om de lämnas - de enda undantagen från tokenvägen. */
1067	  :root[data-process="invert"] #process .process-lead,
1068	  :root[data-process="invert"] #process .process-p,
1069	  :root[data-process="invert"] .principles .ledger-body p{
1070	    color: color-mix(in srgb, var(--c-paper) 78%, var(--c-black));
1071	  }
