1073	  :root[data-process="invert"] .principles .ledger-num{
1074	    color: color-mix(in srgb, var(--c-paper) 62%, var(--c-black));
1075	  }
1076	  /* PLAN 046. Färgfilens odämpade luminans (mean 0,54) läser som en lampa
1077	     mot --c-black (mätt: 11:1). brightness(0.6) är minsta värde som förde
1078	     bildrektangelns mean under 0,34 och p95 under 0,80 vid BÅDA breddema
1079	     (0,62 klarade 1440 men landade på 0,3403 vid 390, över gränsen);
1080	     saturate() behövdes inte, bilden läste inte skrikig vid den nivån.
1081	     Pappersläget dämpas aldrig - denna regel är invert-scopead. */
1082	  :root[data-process="invert"] .process-sheet .p-live{
1083	    filter:grayscale(calc(1 - var(--k6))) contrast(1.05) brightness(0.6);}
1084	
1085	  /* PLAN 019 Step 8. <=1279: arket sticky OVANFÖR texten (order:-1 i
1086	     DOM-ordningen orörd), reducerad plansch 320x360 (K3:s regel: en
1087	     station visas bara på en bredd den beskriver). */
1088	  @media (max-width:1279px){
1089	    .process-grid{grid-template-columns:1fr;row-gap:0;}
1090	    /* PLAN 025 D: 480px bredd -> 564px hög ark (aspect-ratio 320/360 + 24px
1091	       padding), vilket vid låga viewports (720x450) täcker hela skärmen.
1092	       Tredje termen håller >=200px text synlig under arket alltid.
1093	       AVVIKELSE: planens formel (100svh - 200px) räknar inte med sin EGEN
1094	       padding-block (24px): uppmätt lämnade den bara 176px, inte >=200px,
1095	       vid 640/600/450px höjd (samma 24px-underskott vid alla tre). Rättad
1096	       till (100svh - 224px) så att bredden krymper 24px extra och
1097	       padding-block:12px+12px räknas in i budgeten. */
1098	    .process-stick{order:-1;position:sticky;top:0;z-index:2;
1099	      background:var(--bg);padding-block:12px;justify-self:center;
1100	      width:min(100%,480px,calc((100svh - 224px) * 320 / 360));}
1101	    /* PLAN 047: arket är centrerat och smalare än den enkolumns-grid det
1102	       delar med .process-steps (H-08/H-30, lead 2026-09-17). Samma
1103	       width-uttryck och justify-self, ordagrant - annars sticker texten ut
1104	       på båda sidor om arkets ogenomskinliga bakgrund och klipps mitt i
1105	       ordet mellan 640 och 1279px. */
1106	    .process-steps{width:min(100%,480px,calc((100svh - 224px) * 320 / 360));
1107	      justify-self:center;}
1108	    .process-sheet{aspect-ratio:320/360;}
1109	    .process-steps li{padding-block:clamp(32px,5vh,48px);}
1110	
1111	    #p-guides,#p-hatch,#p-ledgers,#p-dim-row,#p-dim-gutter,#p-stations,
1112	    #p-c-gutter,#p-c-row{display:none;}
1113	
1114	    #p-outline{d:path("M0.5 0.5 H319.5 V359.5 H0.5 Z");}
1115	    #p-opening{d:path("M24 56 H296 V209 H24 Z");}
1116	    #p-open-rect,#p-live-img{x:24px;y:56px;width:272px;height:153px;}
1117	    #p-dim-width{d:path("M0 250 H320");}
1118	    #p-lead-169{d:path("M296 56 L306 40 H312");}
1119	    #p-title{d:path("M112 292 H296 V346 H112 Z M112 310 H296 M112 328 H296");}
1120	    #p-rev{x:112px;y:292px;width:184px;height:18px;}
1121	    #p-m320,#p-m768,#p-m1440{font-size:34px;}
1122	  }
1123	
1124	  /* ---------------------------------------------------------- s7, avslutet
1125	     En rad, en adress, ingenting mer. Ligger på den kontinuerliga grunden,
1126	     full bredd under båda spalterna, och stänger sidan i stället för att
1127	     tona ut den. */
1128	  /* Plan 007: .close delade sista viewporten med prisblocket/Hōrai (108px
1129	     toppadding, 274px total höjd av 900). min-height:62svh ger mailto-raden
1130	     en egen skärm vid 1440 och 390, staplat lugnt i mitten. */
1131	  /* PLAN 015: 62svh delade viewporten med liggaren (Astra loop 1 fix 6);
1132	     100svh ger avslutet hela sin skärm, ensamt. Footern är sidans sista
1133	     akt och kan aldrig nå --sc-ps=1 (dokumentet slutar när dess underkant
1134	     möter viewportens): max ps = vh/(vh+vh) = 0,50 vid båda bredderna. */
1135	  .close{position:relative;z-index:1;min-height:100svh;
1136	    display:flex;flex-direction:column;justify-content:center;align-items:flex-start;
1137	    gap:clamp(20px,3vh,32px);
1138	    padding:clamp(64px,12vh,140px) var(--rail-x) clamp(56px,10vh,120px);}
1139	  /* Hårlinjen ritas ur --sc-ps (F-014), ingen transition, ingen JS. */
1140	  .close-rule{width:100%;height:1px;background:var(--hairline-dark);transform-origin:left center;
1141	    transform:scaleX(clamp(0,calc(var(--sc-ps,0) / 0.46),1));}
1142	  .close-mailto{display:inline-flex;align-items:center;min-height:44px;
1143	    font-family:var(--font);font-weight:300;
1144	    font-size:clamp(2rem,6vw,6rem);line-height:1;letter-spacing:-.02em;
1145	    color:#f7f5f0;text-decoration:none;
1146	    border-bottom:1px solid rgba(247,245,240,.42);padding-bottom:.12em;
1147	    transition:border-color .16s var(--ease),color .16s var(--ease);}
1148	  .close-mailto:hover{border-color:#f7f5f0;}
1149	  .close-mailto:active{color:#ffffff;border-color:#ffffff;}
1150	
1151	  @media (max-width:900px){
1152	    .calyx-fig,.horai-fig{flex:none;}
1153	    .calyx-wrap{min-height:66dvh;}
1154	    .horai-wrap{min-height:62dvh;}
1155	    .thesis-grid{grid-template-columns:1fr;}
1156	    /* Bleeden tas bort helt så snart spalterna staplar. Under 900 px finns
